import{_ as n,o as t,c as o,j as a,a as l}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"经典版出版缘起","description":"","frontmatter":{},"headers":[],"relativePath":"books/wanli-shiwunian/03-经典版出版缘起.md","filePath":"books/wanli-shiwunian/03-经典版出版缘起.md","lastUpdated":1792659890000}'),s={name:"books/wanli-shiwunian/03-经典版出版缘起.md"};function r(i,e,d,_,p,c){return t(),o("div",null,[...e[0]||(e[0]=[a("h1",{id:"经典版出版缘起",tabindex:"-1"},[l("经典版出版缘起 "),a("a",{class:"header-anchor",href:"#经典版出版缘起","aria-label":'Permalink to "经典版出版缘起"'},"​")],-1),a("p",null,"《万历十五年》是历史学家黄仁宇先生的代表作，也是一部具有经典意义的历史作品。",-1),a("p",null,"三十多年来，本书英文版被美国多所大学采用为教科书，并两次获得美国国家图书奖（National Book Award）历史类好书的提名；中文版在华语世界也获得如潮好评，成为众多作家、学者、企业家、高校师生的案头必备书，先后荣膺《新周刊》、《书城》“改革开放20年来对中国影响最大的20本书”、第九届深圳读书月“30年30本书”、《中国图书商报》“改革开放30年最具影响力的300本书”和搜狐网“读本好书”经典好书奖等称誉与奖项。",-1),a("p",null,"2006年8月，我们出版了《万历十五年》（增订纪念本），增订文字，精选插图，广受欢迎。应众多读者要求，此次我们隆重推出《万历十五年》（经典版），以增订纪念本为基础，采用布面精装，进一步完善全书文字，增收多幅彩色历史图片，并特别制作《经典的历程——〈万历十五年〉中文之旅》，以飨读者。",-1),a("p",null,"中华书局编辑部",-1),a("p",null,"2014年5月",-1)])])}const f=n(s,[["render",r]]);export{m as __pageData,f as default};
